#include "Undo/UndoManager.h"
namespace myvocal { void UndoManager::push(std::unique_ptr<Command>c){if(!c)return;c->redo();m_undo.push_back(std::move(c));m_redo.clear();}void UndoManager::undo(){if(m_undo.empty())return;auto c=std::move(m_undo.back());m_undo.pop_back();c->undo();m_redo.push_back(std::move(c));}void UndoManager::redo(){if(m_redo.empty())return;auto c=std::move(m_redo.back());m_redo.pop_back();c->redo();m_undo.push_back(std::move(c));}bool UndoManager::canUndo()const noexcept{return !m_undo.empty();}bool UndoManager::canRedo()const noexcept{return !m_redo.empty();}void UndoManager::clear(){m_undo.clear();m_redo.clear();}}
